import{c as a,Q as e,j as d,m as r}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"LoadDataWithSparse","description":"","frontmatter":{},"headers":[{"level":1,"title":"LoadDataWithSparse","slug":"loaddatawithsparse"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadDataWithSparse.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadDataWithSparse.md"}'),l={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadDataWithSparse.md"};function s(i,t,o,n,h,p){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="loaddatawithsparse" tabindex="-1">LoadDataWithSparse <a class="header-anchor" href="#loaddatawithsparse" aria-label="Permalink to &quot;LoadDataWithSparse&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于搬运存放在B1里的512B的稠密权重矩阵到B2里，同时读取128B的索引矩阵用于稠密矩阵的稀疏化。索引矩阵的数据类型为int2，需要拼成int8的数据类型，再传入接口。</p><p>索引矩阵在一个int8的地址中的排布是逆序排布的，例如：索引矩阵1 2 0 1 0 2 1 0，在地址中的排布为1 0 2 1 0 1 2 0，其中1 0 2 1（对应索引矩阵前四位1 2 0 1）为一个int8，0 1 2 0（对应索引矩阵后四位0 2 1 0）为一个int8。</p><p>索引矩阵的功能说明参考<a href="./../矩阵计算/MmadWithSparse.html">MmadWithSparse</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = int8_t, typename U = uint8_t, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;T&gt;, int8_t&gt;::value, bool&gt;::type = true, typename Std::enable_if&lt;Std::is_same&lt;PrimT&lt;U&gt;, uint8_t&gt;::value, bool&gt;::type = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void LoadDataWithSparse(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const LocalTensor&lt;U&gt;&amp; idx, const LoadData2dParams&amp; loadDataParam)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>dst、src的数据类型。</td></tr><tr><td>U</td><td>idx的数据类型。 当dst、src、idx为基础数据类型时，T和U必须为uint8_t类型，否则编译失败。 当dst、src、idx为TensorTrait类型时，T和U的LiteType必须为int8_t类型，否则编译失败。 最后两个模板参数仅用于上述数据类型检查，用户无需关注。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，支持的TPosition为B2，LocalTensor的起始地址需要512字节对齐。 支持的数据类型为int8_t。 数据连续排列顺序要求为小N大Z格式。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor，支持的TPosition为B1，LocalTensor的起始地址需要32字节对齐。 支持的数据类型为int8_t。</td></tr><tr><td>idx</td><td>输入</td><td>源操作数，类型为LocalTensor，支持的TPosition为B1，LocalTensor的起始地址需要32字节对齐。 支持的数据类型为int8_t。</td></tr><tr><td>loadDataParam</td><td>输入</td><td>LoadData参数结构体，LoadData2DParams类型，详细说明参考LoadData2DParams结构体内参数说明。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>repeat=0表示不执行。</li><li>每次迭代中的startIndex不能小于零。</li><li>不支持转置功能。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>详细用例请参考<a href="./../矩阵计算/MmadWithSparse.html">MmadWithSparse</a>。</p>`,20)])])}const u=a(l,[["render",s]]);export{m as __pageData,u as default};
